// Applied rules: [C3]
// Skipped rules: [II_inl: The only concrete callee hit is BrotliParseAsUTF8 already called from a tiny loop, but the miss reason is TooCostly and the target function body is not shown for audit. Per rule guidance, forcing inline without inspecting/splitting the callee is risky; moreover the caller already has #[inline], so the safer first move is the local C3 cleanup. No concrete callee rewrite is committed in this plan.]
#[inline]
pub unsafe fn BrotliIsMostlyUTF8(
    mut data: *const uint8_t,
    pos: size_t,
    mask: size_t,
    length: size_t,
    min_fraction: c_double,
) -> c_int {
    let base = data;
    let ring_mask = mask;
    let len = length;
    let threshold = min_fraction * len as c_double;

    let mut size_utf8: size_t = 0 as size_t;
    let mut i: size_t = 0 as size_t;
    while i < len {
        let mut symbol: c_int = 0;
        let bytes_read: size_t = BrotliParseAsUTF8(
            &raw mut symbol,
            // SAFETY: `base` is the original caller-provided raw pointer; this preserves
            // the original unchecked ring-buffer address computation `(pos + i) & mask`
            // and does not add any new aliasing or bounds assumptions beyond the original code.
            unsafe { base.offset((pos.wrapping_add(i) & ring_mask) as isize) } as *const uint8_t,
            len.wrapping_sub(i),
        );
        i = (i as c_ulong).wrapping_add(bytes_read as c_ulong) as size_t as size_t;
        if symbol < 0x110000 as c_int {
            size_utf8 = (size_utf8 as c_ulong).wrapping_add(bytes_read as c_ulong) as size_t
                as size_t;
        }
    }
    return if size_utf8 as c_double > threshold {
        BROTLI_TRUE
    } else {
        BROTLI_FALSE
    };
}

